```java
@Override
public Collection<String> getApplicableElements() {
    return Collections.singletonList(TAG_SELECTOR);
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    NodeList children = element.getChildNodes();
    int lastItemIndex = -1;
    // find last item index
    for (int i = children.getLength() - 1; i >= 0; i--) {
        Node child = children.item(i);
        if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getLocalName())) {
            lastItemIndex = i;
            break;
        }
    }

    if (lastItemIndex == -1) return;

    for (int i = 0; i < lastItemIndex; i++) {
        Node child = children.item(i);
        if (child.getNodeType() != Node.ELEMENT_NODE || !TAG_ITEM.equals(child.getLocalName())) {
            continue;
        }
        Element item = (Element) child;
        if (!hasStateQualifier(item)) {
            context.report(ISSUE, item, context.getLocation(item), "This item will match all states, making subsequent items unreachable; only the last item should omit state qualifiers");
        }
    }
}

private boolean hasStateQualifier(Element item) {
    NamedNodeMap attrs = item.getAttributes();
    for (int i = 0; i < attrs.getLength(); i++) {
        Attr attr = (Attr) attrs.item(i);
        if (attr.getLocalName() != null && attr.getLocalName().startsWith("state_")) {
            return true;
        }
    }
    return false;
}
```

